window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[51]={"id":"051","numero":51,"titre":"Troubles mictionnels de l'enfant","objectifs":[{"id":"51-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique en cas de trouble mictionnel : enquête clinique","contenu":"<p>Le diagnostic est <span class=\"kw-alerte\">CLINIQUE</span> : interrogatoire complet + examen physique. Trois axes structurent l’enquête.</p>\n\n      <h4>1. Anamnèse</h4>\n      <ul>\n        <li><strong>Modalités d’apprentissage</strong> et acquisition de la propreté.</li>\n        <li><strong>Habitudes mictionnelles</strong> : nombre de mictions / jour, utilisation des toilettes scolaires (disponibilité, propreté, papier toilette), apports hydriques quotidiens.</li>\n        <li><strong>Symptomatologie</strong> actuelle/passée, caractère récent ou ancien.</li>\n        <li>Utilisation de <strong>protections</strong>, retentissement psychosocial.</li>\n        <li><strong>ATCD</strong> de troubles fonctionnels similaires chez <span class=\"kw-clinique\">les</span> parents ou la fratrie.</li>\n        <li>Développements <strong>psychomoteur et statural</strong>.</li>\n        <li>Mesures déjà mises en place.</li>\n      </ul>\n\n      <h4>2. Troubles associés à rechercher systématiquement</h4>\n      <ul>\n        <li><strong>Uropathies malformatives</strong> : <span class=\"kw-etio\">valves de l’urètre postérieur</span>, <span class=\"kw-etio\">système urinaire double</span> avec uretère ectopique ou <span class=\"kw-etio\">urétérocèle</span>, <span class=\"kw-etio\">épispadias</span>, <span class=\"kw-etio\">exstrophie vésicale</span>.</li>\n        <li><strong>Pathologies organiques</strong> : <span class=\"kw-etio\">diabète</span>, <span class=\"kw-ci\">insuffisance rénale</span>.</li>\n        <li><strong>ATCD d’infections urinaires</strong> : redouter un <span class=\"kw-etio\">reflux vésico-urétéral</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Douleurs abdominales</span> / troubles ano-rectaux</strong> : <span class=\"kw-etio\">constipation</span>, encoprésie.</li>\n        <li><strong>Pathologies neurologiques</strong> : troubles de la motricité des MI, retard d’acquisition de la marche, chutes fréquentes, fat<span class=\"kw-chiffre\">iga</span>bilité.</li>\n        <li><strong>Sommeil</strong> : profondeur et durée, difficultés d’éveil, ronflements nocturnes, apnées (<span class=\"kw-clinique\">SAOS</span>).</li>\n        <li><strong>Environnements</strong> : social et familial (<span class=\"kw-alerte\">maltraitance</span>), contexte scolaire et psychologique.</li>\n      </ul>\n\n      <h4>3. Examen clinique</h4>\n      <ul>\n        <li><strong>Inspection de la culotte</strong> : recherche de st<span class=\"kw-chiffre\">igm</span>ates de fuites urinaires ou de selles.</li>\n        <li><strong>Recherche d’un globe vésical</strong> (principales causes de RAU : inflammation locale, IU, fécalome, obstruction organique des voies urinaires, atteinte médullaire, EI <span class=\"kw-etio\">médicamenteux</span>).</li>\n        <li><strong>Examen des OGE</strong> : palpation des testicules, aspect de la verge et du méat, vulvite.</li>\n        <li><strong>Aspect du jet urinaire</strong>.</li>\n        <li>Recherche d’un <strong>encombrement stercoral</strong> (fécalome) à la palpation abdominale.</li>\n        <li><strong>Examen neurologique complet</strong> : motricité MI, sensibilité périnéale, st<span class=\"kw-chiffre\">igm</span>ates cutanés de la région dorso-lombaire (<em>lipome, angiome, « touffe » de poils</em> = maladie médullaire <span class=\"kw-etio\">congénitale</span>).</li>\n        <li><strong>Examen neuro-orthopédique</strong> : pied creux, inégalité de longueur des MI, scoliose, troubles trophiques.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Au terme de l’enquête clinique</strong> : <span class=\"kw-bio\">bandelette urinaire (BU)</span> systématique pour <strong>exclure une <span class=\"kw-clinique\">infection urinaire</span></strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-clinique\">Infection urinaire</span> · 57 — Maltraitance, enfant en danger</em></p>","frequence":0},{"id":"51-2","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la démarche diagnostique en cas de trouble mictionnel : examens paracliniques","contenu":"<p>L’examen clinique seul suffit le plus souvent pour identifier une cause fonctionnelle.</p>\n\n      <h4>Examens de <span class=\"kw-chiffre\">première intention</span></h4>\n      <ul>\n        <li><strong>Catalogue mictionnel</strong> : heure et volume de chaque miction, quantité de prise de boissons, épisodes de fuites — <span class=\"kw-chiffre\">pendant 48 heures</span>.</li>\n        <li><strong><span class=\"kw-bio\">Bandelette urinaire</span> (<span class=\"kw-bio\">BU</span>)</strong> : exclure une infection.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Pas d’examen paraclinique</strong> en cas de fuites urinaires <span class=\"kw-chiffre\">sans dysurie</span>.\n      </div>\n\n      <h4>Examens à proposer devant troubles persistants ou atypiques</h4>\n      <ul>\n        <li><strong>Fuites urinaires non isolées ou résistantes</strong> : <span class=\"kw-imagerie\">échographie réno-vésicale + mesure du résidu post-mictionnel (RPM)</span>.</li>\n        <li><strong>Autres examens</strong> (après avis spécialisé) : <span class=\"kw-imagerie\">débitmétrie + RPM ± bilan urodynamique (BUD)</span>.</li>\n      </ul>\n\n      <h4>Objectif des paracliniques = rechercher une étiologie organique</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Valves de l’urètre postérieur</span> (garçon ++) : <span class=\"kw-clinique\">globe vésical</span>, dysurie.</li>\n        <li><span class=\"kw-etio\">Abouchement ectopique de l’uretère</span> du pyélon supérieur d’un <span class=\"kw-etio\">système urinaire double</span> (fille) : incontinence urinaire permanente avec mictions conservées.</li>\n        <li><span class=\"kw-etio\">Neuro-vessie congénitale</span> par maladie médullaire <span class=\"kw-etio\">congénitale</span> ou <span class=\"kw-alerte\">dysraphisme spinal</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-clinique\">Infection urinaire</span></em></p>","frequence":1},{"id":"51-3","rang":"A","rubrique":"Étiologies","titre":"Connaître la démarche diagnostique en cas de trouble mictionnel : orientation diagnostique","contenu":"<p>Trois grandes catégories étiologiques structurent la sémiologie : <strong>dysfonctions du bas appareil urinaire</strong>, <strong>malformations congénitales</strong> et <strong>causes neurologiques</strong>.</p>\n\n      <h4>A. Dysfonctions du bas appareil urinaire diurnes (TUBA)</h4>\n      <p><span class=\"kw-def\">TUBA</span> = « <em>Lower Urinary Tract Symptoms</em> », ou troubles urinaires du bas appareil = <strong>incontinence fonctionnelle</strong> chez l’enfant.</p>\n\n      <h5 style=\"margin:10px 0 4px;\">Anomalies de la phase de remplissage</h5>\n      <ul>\n        <li><strong>Contraction désinhibée primitive du détrusor</strong> pendant le remplissage = ↗ pression vésicale au-delà de la pression de clôture sphinctérienne = <span class=\"kw-clinique\">fuite urinaire</span>.</li>\n        <li>Persistance d’une <strong>hyperactivité détrusorienne <span class=\"kw-chiffre\">&gt; 5 ans</span></strong> (anciennement « vessie hyperactive ») = fuites urinaires diurnes ± nocturnes, <span class=\"kw-clinique\">urgenturie</span>, <span class=\"kw-clinique\">pollakiurie</span> (<span class=\"kw-chiffre\">&gt; 7 mictions/jour chez un enfant ≥ 5 ans</span>) sur immaturité vésicale — favorise IU et/ou reflux vésico-urétéral.</li>\n        <li><strong>Manœuvres de retenue</strong> (l’enfant essaie de maîtriser la fuite par contraction sphinctérienne) : <span class=\"kw-clinique\">accroupissement, pincement de verge, croisement des jambes, agitation, debout sur la pointe des pieds</span>.</li>\n        <li>Peut être secondaire à une <span class=\"kw-def\">« épine irritative »</span> : <span class=\"kw-clinique\">IU</span>, <span class=\"kw-etio\">constipation</span>, RPM, <span class=\"kw-etio\">oxyurose</span>, <span class=\"kw-etio\">irritation des OGE</span>.</li>\n      </ul>\n\n      <h5 style=\"margin:10px 0 4px;\">Anomalies de la phase de vidange</h5>\n      <p><span class=\"kw-etio\">Dyssynergie vésico-sphinctérienne</span> : absence de relâchement sphinctérien au moment de la miction.</p>\n      <p><strong>Causes (DSV primaire = survient sur vessie rétentionniste)</strong></p>\n      <ul>\n        <li>Mauvaises habitudes mictionnelles.</li>\n        <li><span class=\"kw-clinique\">Évolution</span> d’une immaturité vésicale (contraction excessive du sphincter pour éviter <span class=\"kw-clinique\">les</span> fuites).</li>\n        <li>Contexte psychologique particulier, <span class=\"kw-alerte\">abus sexuels</span>.</li>\n      </ul>\n      <p><strong>Conséquences</strong></p>\n      <ul>\n        <li>Défaut de relâchement périnéal lors de la miction → apparition d’un <strong>RPM</strong>.</li>\n        <li>Sa persistance peut aboutir à une <em>grande vessie rétentionniste à mictions rares</em> par <span class=\"kw-clinique\">hypocontractilité détrusorienne</span>.</li>\n      </ul>\n\n      <h4>B. Malformations congénitales des voies urinaires</h4>\n\n      <h5 style=\"margin:10px 0 4px;\">Implantation ectopique d’urètre (fille)</h5>\n      <ul>\n        <li>Dans le cadre d’une <strong>duplication de la voie urinaire</strong> : l’uretère du pyélon supérieur peut s’implanter en dehors de la vessie et court-circuiter le système sphinctérien (abouchement dans la partie terminale de l’urètre, le vagin ou la vulve).</li>\n        <li><strong>Fuites d’urine permanentes</strong>, entrecoupées de mictions normales — <span class=\"kw-clinique\">vulvovaginites à répétition</span>.</li>\n      </ul>\n\n      <h5 style=\"margin:10px 0 4px;\">Valves de l’urètre postérieur (garçon)</h5>\n      <ul>\n        <li>Persistance d’un ou plusieurs <strong>replis muqueux urétrogénitaux</strong> en dessous du <em>veru montanum</em> = obstacle urétral à l’écoulement de l’urine.</li>\n        <li><span class=\"kw-clinique\">Globe vésical</span> avec jet urinaire absent ou en goutte-à-goutte, <span class=\"kw-clinique\">dysurie</span>.</li>\n        <li>Apparition d’une <strong>vessie de lutte</strong> selon le degré d’obstruction et possible <span class=\"kw-alerte\">dégradation de la fonction rénale</span>.</li>\n        <li><em>(Rang C)</em> Confirmation par <span class=\"kw-imagerie\">cystographie rétrograde</span> au moindre doute → <span class=\"kw-ttt\">résection endoscopique des valves</span> (<span class=\"kw-alerte\">urgence</span> médico-chirurgicale ; surveiller le <span class=\"kw-alerte\">syndrome de levée d’obstacle</span>).</li>\n      </ul>\n\n      <h4>C. Causes neurologiques</h4>\n      <ul>\n        <li><strong>TOUJOURS évoquer une vessie neurologique</strong> → rechercher systématiquement une <span class=\"kw-alerte\">anomalie médullaire congénitale occulte</span> lorsque la clinique et l’<span class=\"kw-clinique\">évolution</span> ne correspondent pas à l’hypothèse fonctionnelle ou que <span class=\"kw-clinique\">les</span> troubles persistent malgré une PEC adaptée.</li>\n      </ul>\n\n      <h4>Complications à connaître</h4>\n      <ul>\n        <li><strong>Troubles ano-rectaux</strong> : <span class=\"kw-etio\">constipation</span>, douleur défécatoire, encoprésie.</li>\n        <li><strong>Complications urologiques</strong> : vessie de lutte, reflux vésico-urétéral, <span class=\"kw-alerte\">insuffisance rénale</span> dans <span class=\"kw-clinique\">les</span> formes graves.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-clinique\">Infection urinaire</span> · 283 — <span class=\"kw-clinique\">Constipation</span></em></p>","frequence":1},{"id":"51-4","rang":"B","rubrique":"Étiologies","titre":"Connaître les troubles associées aux troubles de la miction","contenu":"<p><span class=\"kw-clinique\">Les</span> troubles mictionnels de l’enfant s’associent fréquemment à des <span class=\"kw-def\">comorbidités</span> psychiques, neuro-développementales et respiratoires nocturnes — à rechercher systématiquement.</p>\n\n      <h4>Troubles psychiques</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Repli sur soi</span>, <span class=\"kw-clinique\">stress émotionnel</span>, perte de l’estime de soi.</li>\n        <li><strong>Troubles du développement et des apprentissages</strong>.</li>\n      </ul>\n\n      <h4>Troubles psychiatriques</h4>\n      <div class=\"callout callout-info\">\n        <span class=\"kw-clinique\">Les</span> enfants souffrant de troubles mictionnels ont <span class=\"kw-chiffre\">2 à 4×</span> plus de troubles du comportement, en particulier un <span class=\"kw-alerte\">TDAH</span>.\n      </div>\n\n      <h4>Troubles du sommeil</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Apnées du sommeil</span>.</li>\n        <li><span class=\"kw-clinique\">Parasomnies</span>, notamment chez <span class=\"kw-clinique\">les</span> enfants atteints d’<span class=\"kw-etio\">énurésie</span>.</li>\n      </ul>\n\n      <h4>Troubles respiratoires nocturnes</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">SAHOS</span> (ronflement) : fréquemment rapporté dans l’<strong>énurésie primaire isolée</strong>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 110 — Trouble sommeil</em></p>","frequence":0},{"id":"51-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une instabilité vésicale","contenu":"<h4>Définition</h4>\n      <p><span class=\"kw-etio\">Instabilité vésicale</span> = persistance d’une <strong>hyperactivité détrusorienne au-delà de <span class=\"kw-chiffre\">5 ans</span></strong> (anciennement « vessie hyperactive »).</p>\n\n      <h4><span class=\"kw-def\">Physiopathologie</span></h4>\n      <p>Contraction <strong>désinhibée et primitive du détrusor</strong> pendant la phase de remplissage : élève la pression vésicale au-delà de la pression de clôture sphinctérienne et provoque la <span class=\"kw-clinique\">fuite urinaire</span>.</p>\n\n      <h4>Manifestations cliniques</h4>\n      <ul>\n        <li><strong>Fuites urinaires</strong> <span class=\"kw-clinique\">diurnes</span>, éventuellement <span class=\"kw-clinique\">nocturnes</span>.</li>\n        <li><span class=\"kw-clinique\">Urgenturie</span> et <span class=\"kw-clinique\">pollakiurie</span> (<span class=\"kw-chiffre\">&gt; 7 mictions/jour chez un enfant ≥ 5 ans</span>) sur immaturité vésicale.</li>\n        <li><strong>Manœuvres de retenue</strong> (l’enfant tente de maîtriser la fuite par contraction sphinctérienne) : <span class=\"kw-clinique\">accroupissement, pincement de verge, croisement des jambes, agitation, debout sur la pointe des pieds</span>.</li>\n      </ul>\n\n      <h4>Complications</h4>\n      <ul>\n        <li>Favorise <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">infections urinaires</span> et/ou un <span class=\"kw-etio\">reflux vésico-urétéral</span>.</li>\n      </ul>\n\n      <h4><span class=\"kw-def\">Diagnostic différentiel</span> — hyperactivité détrusorienne secondaire à une « épine irritative »</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Infection urinaire</span>.</li>\n        <li><span class=\"kw-etio\">Constipation</span>.</li>\n        <li><span class=\"kw-clinique\">Résidu post-mictionnel</span>.</li>\n        <li><span class=\"kw-etio\">Oxyurose</span>.</li>\n        <li><span class=\"kw-etio\">Irritation des OGE</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Repères de prise en charge.</strong>\n        <ul style=\"margin:6px 0 0;\">\n          <li><strong>Régularisation des habitudes hydriques et mictionnelles</strong> et prise en charge d’une éventuelle <em>épine irritative</em>.</li>\n          <li>Amélioration des <strong>postures mictionnelles</strong>.</li>\n          <li><span class=\"kw-ttt\">Anticholinergiques</span> si nécessaire (<span class=\"kw-alerte\">⚠ contre-indiqués en cas de dyssynergie vésico-sphinctérienne</span>).</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — <span class=\"kw-clinique\">Infection urinaire</span> · 283 — <span class=\"kw-clinique\">Constipation</span> · 57 — Maltraitance, enfant en danger</em></p>","frequence":0},{"id":"51-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une énurésie primaire","contenu":"<h4>Définition</h4>\n      <p><span class=\"kw-etio\">Énurésie</span> = fuite involontaire d’urine pendant le <strong>sommeil</strong> chez un enfant <span class=\"kw-chiffre\">≥ 5 ans</span>.</p>\n\n      <h4>Sous-types</h4>\n      <ul>\n        <li><strong>Primaire</strong> : l’enfant n’a jamais eu de nuit sèche sur une période <span class=\"kw-chiffre\">&gt; 6 mois</span> depuis la naissance.</li>\n        <li><strong>Isolée ou monosymptomatique</strong> : aucun autre symptôme associé (notamment diurne).</li>\n      </ul>\n\n      <h4>Repères épidémiologiques</h4>\n      <ul>\n        <li><strong><span class=\"kw-chiffre\">10 %</span></strong> (<span class=\"kw-chiffre\">20 % dans la LiSA</span>) ont un <span class=\"kw-clinique\">TDAH associé</span>.</li>\n        <li><strong><span class=\"kw-chiffre\">30 à 60 %</span></strong> de notion familiale.</li>\n      </ul>\n\n      <h4>Démarche diagnostique</h4>\n      <ul>\n        <li><span class=\"kw-def\">Diagnostic positif</span> = <span class=\"kw-alerte\">CLINIQUE</span>.</li>\n        <li><strong>Aucun examen d’imagerie en 1ʳᵉ intention</strong>.</li>\n        <li>Apprécier le <strong>degré de sévérité</strong> : <span class=\"kw-chiffre\">1 nuit/mois · ≥ 1 nuit/semaine · toutes les nuits</span>.</li>\n      </ul>\n\n      <h4>Sous-types de l’énurésie primaire isolée — 2 mécanismes physiopathologiques</h4>\n      <ul>\n        <li><strong>Polyurique par inversion du cycle de l’ADH</strong> : volume urinaire nocturne &gt; volume diurne, avec <span class=\"kw-bio\">osmolarité</span> urinaire plus basse la nuit.</li>\n        <li><strong>Faible capacité vésicale</strong> : capacité vésicale fonctionnelle <span class=\"kw-chiffre\">&lt; 70 %</span> de la capacité théorique (mesurée sur <span class=\"kw-clinique\">calendrier mictionnel de 48 h</span>).</li>\n      </ul>\n\n      <h4>Type d’énurésie et prise en charge — 3 mécanismes</h4>\n\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Prise en charge</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Trouble de l’architecture du sommeil</strong></td>\n            <td>Thérapies de conditionnement.</td>\n          </tr>\n          <tr>\n            <td><strong>Immaturité de la régulation hormonale centrale</strong> (inversion du cycle de sécrétion ADH)</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ttt\">Réduction</span> des apports hydriques.</li>\n                <li>Traitement par <span class=\"kw-ttt\">desmopressine</span>.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Dysfonctionnement diurne et nocturne</strong></td>\n            <td>\n              <ul>\n                <li><strong>Régularisation des habitudes hydriques et mictionnelles</strong> : arrêt des boissons après <span class=\"kw-chiffre\">19 h</span>, miction avant le coucher, accès facile aux toilettes la nuit.</li>\n                <li><span class=\"kw-ttt\">Anticholinergiques</span>.</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 110 — Trouble sommeil</em></p>","frequence":2}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU & Pièges » et « Stratégie & CAT » : à compléter après revue clinique.</p>"}],"strategie":{"urgence":"<p><strong>Valves de l'urètre postérieur <span class=\"q\">— nourrisson garçon</span></strong></p><p><span class=\"kw-ttt\">Résection endoscopique des valves</span> — <span class=\"kw-alerte\">urgence</span> médico-chirurgicale ; surveiller le <span class=\"kw-alerte\">syndrome de levée d'obstacle</span> (<span class=\"kw-bio\">troubles hydro-électrolytiques</span>)</p><ul><li><span class=\"kw-alerte\">Obstacle urétral</span> à l'écoulement de l'urine : <span class=\"kw-clinique\">globe vésical</span>, jet absent ou en goutte-à-goutte, <span class=\"kw-clinique\">dysurie</span></li><li><span class=\"kw-clinique\">Évolution</span> vers une <span class=\"kw-alerte\">vessie de lutte</span> puis une <span class=\"kw-alerte\">dégradation de la fonction rénale</span></li></ul><p><strong>Rétention aiguë d'urine <span class=\"q\">— globe vésical</span></strong></p><p>Palpation abdominale systématique à la recherche d'un <span class=\"kw-clinique\">globe vésical</span></p><ul><li>Causes à rechercher : <span class=\"kw-etio\">inflammation locale ou infection urinaire</span>, <span class=\"kw-etio\">fécalome</span>, <span class=\"kw-etio\">obstruction organique des voies urinaires</span>, <span class=\"kw-etio\">atteinte médullaire</span>, <span class=\"kw-etio\">effet secondaire médicamenteux</span></li></ul>","hospit":"<p>Prise en charge <span class=\"kw-def\">ambulatoire</span> dans la majorité des cas : la démarche clinique retient le plus souvent une <span class=\"kw-def\">cause fonctionnelle</span> accessible à des mesures simples.</p><p><strong>Avis spécialisé (uro-néphrologie pédiatrique)</strong></p><ul><li>Suspicion de <span class=\"kw-etio\">cause neurologique</span> ou <span class=\"kw-etio\">urologique</span> organique</li><li>Hyperactivité détrusorienne d'allure <span class=\"kw-clinique\">neurologique</span> (signes d'alerte médullaires)</li><li><span class=\"kw-etio\">Valves de l'urètre postérieur</span> chez le garçon</li><li>Troubles persistant malgré une prise en charge adaptée</li></ul><p><strong>Explorations réservées au 2ᵉ temps</strong></p><ul><li><span class=\"kw-imagerie\">Échographie réno-vésicale + mesure du RPM</span> si fuites non isolées ou résistantes</li><li><span class=\"kw-imagerie\">Débitmétrie + RPM</span> ± <span class=\"kw-imagerie\">bilan urodynamique</span>, après avis spécialisé</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Stigmate cutané lombo-sacré</span> (lipome, angiome, « touffe » de poils) → <span class=\"kw-etio\">maladie médullaire congénitale</span></li><li><span class=\"kw-alerte\">Anomalie de la motricité des membres inférieurs</span> ou de la <span class=\"kw-clinique\">sensibilité périnéale</span></li><li><span class=\"kw-alerte\">Signes neuro-orthopédiques</span> : pied creux, inégalité de longueur des MI, scoliose, troubles trophiques</li><li><span class=\"kw-alerte\">Globe vésical</span> avec jet absent ou en goutte-à-goutte → obstacle (<span class=\"kw-etio\">valves de l'urètre postérieur</span>)</li><li><span class=\"kw-alerte\">Dégradation de la fonction rénale</span> / <span class=\"kw-alerte\">insuffisance rénale</span> (vessie de lutte)</li><li><span class=\"kw-clinique\">Incontinence urinaire permanente</span> avec mictions conservées → <span class=\"kw-etio\">abouchement ectopique de l'uretère</span> (fille)</li><li>Contexte de <span class=\"kw-alerte\">maltraitance</span> ou d'<span class=\"kw-alerte\">abus sexuels</span></li></ul>","principes":"<p>La majorité des troubles relève de <strong>mesures simples</strong> : <span class=\"kw-ttt\">régularisation des habitudes hydriques et mictionnelles</span> + traitement d'une éventuelle <span class=\"kw-def\">« épine irritative »</span> (<span class=\"kw-etio\">infection urinaire</span>, <span class=\"kw-etio\">constipation</span>, <span class=\"kw-etio\">oxyurose</span>) et d'un trouble global de l'élimination.</p><p><strong>Instabilité vésicale <span class=\"q\">— hyperactivité détrusorienne</span></strong></p><p><span class=\"kw-ci\">Anticholinergiques contre-indiqués en cas de dyssynergie vésico-sphinctérienne</span></p><ul><li><span class=\"kw-ttt\">Régularisation des habitudes hydriques et mictionnelles</span> + traitement de l'<span class=\"kw-def\">épine irritative</span></li><li>Amélioration des <span class=\"kw-ttt\">postures mictionnelles</span></li><li><span class=\"kw-ttt\">Anticholinergiques</span> si nécessaire</li></ul><p><strong>Énurésie primaire nocturne isolée <span class=\"q\">— selon le mécanisme</span></strong></p><ul><li>Trouble de l'architecture du sommeil → <span class=\"kw-ttt\">thérapies de conditionnement</span></li><li>Inversion du cycle de l'<span class=\"kw-bio\">ADH</span> → <span class=\"kw-ttt\">réduction des apports hydriques</span> + <span class=\"kw-ttt\">desmopressine</span></li><li>Dysfonctionnement diurne et nocturne → <span class=\"kw-ttt\">régularisation hydrique et mictionnelle</span> (arrêt des boissons après <span class=\"kw-chiffre\">19 h</span>, miction avant le coucher, accès facile aux toilettes la nuit) + <span class=\"kw-ttt\">anticholinergiques</span></li></ul>","suivi":"<p><strong>Outil de <span class=\"kw-def\">suivi</span> :</strong> <span class=\"kw-clinique\">catalogue mictionnel</span> sur <span class=\"kw-chiffre\">48 h</span> (heure et volume des mictions, apports hydriques, épisodes de fuites) pour objectiver <span class=\"kw-clinique\">les</span> troubles et quantifier la sévérité.<br><strong>Sévérité de l'énurésie :</strong> <span class=\"kw-chiffre\">1 nuit/mois</span> · <span class=\"kw-chiffre\">≥ 1 nuit/semaine</span> · <span class=\"kw-chiffre\">toutes les nuits</span>.<br><strong>Escalade :</strong> <span class=\"kw-imagerie\">échographie réno-vésicale + RPM</span> si <span class=\"kw-clinique\">fuites non isolées ou résistantes au traitement d'épreuve</span>.<br><strong>Après résection de valves :</strong> surveiller le <span class=\"kw-alerte\">syndrome de levée d'obstacle</span> (<span class=\"kw-bio\">troubles hydro-électrolytiques</span>).</p>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/nephrologie-chirurgie-urologique/troubles-miction","label":"Collège Pédiatrie — Troubles mictionnels"}],"cards":[{"i":"28615d73103e","n":51,"o":"51-1","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de trouble mictionnel : enquête clinique","q":"Quels types de troubles organiques et de pathologies neurologiques doit-on systématiquement rechercher en cas de troubles mictionnels chez l'enfant ?","a":"<ul><li><strong>Pathologies organiques</strong> : <strong>diabète</strong>, insuffisance rénale.</li><li><strong>Pathologies neurologiques</strong> : troubles de la motricité des membres inférieurs, retard d'acquisition de la marche, chutes fréquentes, fatigabilité. La présence de <strong>stigmates cutanés dorso-lombaires</strong> (lipome, angiome, « touffe » de poils) doit faire suspecter une maladie médullaire congénitale.</li><li>Il faut aussi rechercher des <strong>uropathies malformatives</strong> telles que: valves de l’urètre postérieur, système urinaire double avec uretère ectopique ou urétérocèle, épispadias, exstrophie vésicale.</li></ul>"},{"i":"323f02245e2f","n":51,"o":"51-1","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de trouble mictionnel : enquête clinique","q":"Quels sont les éléments clés à rechercher lors de l'anamnèse face à des troubles mictionnels chez l'enfant ?","a":"<ul><li>Les <strong>modalités d'apprentissage et d'acquisition de la propreté</strong>.</li><li>Les <strong>habitudes mictionnelles</strong> (nombre de mictions, utilisation des toilettes scolaires, apports hydriques).</li><li>La <strong>symptomatologie actuelle/passée</strong> et son caractère.</li><li>L'utilisation de protections et le <strong>retentissement psychosocial</strong>.</li><li>Les <strong>antécédents familiaux</strong> de troubles fonctionnels.</li><li>Le développement psychomoteur et statural.</li><li>Les mesures déjà mises en place.</li></ul>"},{"i":"787c229b8acd","n":51,"o":"51-1","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de trouble mictionnel : enquête clinique","q":"Quels sont les éléments prioritaires de l'examen clinique chez un enfant présentant des troubles mictionnels ?","a":"<ul><li><strong>Inspection de la culotte</strong> : recherche de stigmates de fuites urinaires ou de selles.</li><li>Recherche d'un <strong>globe vésical</strong>.</li><li>Examen des <strong>organes génitaux externes</strong> (OGE).</li><li>Évaluation de l'aspect du <strong>jet urinaire</strong>.</li><li>Recherche d'un <strong>encombrement stercoral</strong> (fécalome) à la palpation abdominale.</li><li>Un <strong>examen neurologique complet</strong>, incluant la motricité des membres inférieurs, la sensibilité périnéale, et la recherche de stigmates cutanés dorso-lombaires.</li><li>Un examen <strong>neuro-orthopédique</strong> (pied creux, inégalité de longueur des MI, scoliose, troubles trophiques).</li><li>La réalisation systématique d'une <strong>bandelette urinaire (BU)</strong> pour exclure une infection urinaire.</li></ul>"},{"i":"7918ba6a2376","n":51,"o":"51-1","u":"Diagnostic positif","t":"Connaître la démarche diagnostique en cas de trouble mictionnel : enquête clinique","q":"Quelle est l'approche clinique initiale face à des troubles mictionnels chez l'enfant ?","a":"<p>L'approche initiale repose sur une enquête clinique structurée en trois axes : l'<strong>anamnèse complète</strong>, la recherche de <strong>troubles associés</strong>, et un <strong>examen physique</strong> détaillé.</p>"},{"i":"17960ba83a8f","n":51,"o":"51-3","u":"Étiologies","t":"Connaître la démarche diagnostique en cas de trouble mictionnel : orientation diagnostique","q":"Quelles sont les malformations congénitales à rechercher en cas de troubles mictionnels de l'enfant ?","a":"<p>Il faut rechercher principalement :</p><ul><li>Une <strong>implantation ectopique d'uretère</strong> chez la fille (l'uretère du pyélon supérieur en cas de duplication de la voie urinaire peut s'aboucher en dehors de la vessie, entraînant des <strong>fuites d'urine permanentes</strong> entrecoupées de mictions normales).</li><li>Des <strong>valves de l'urètre postérieur</strong> chez le garçon (persistance de replis muqueux sous le veru montanum, créant un obstacle urétral, se manifestant par un <strong>jet urinaire absent ou en goutte-à-goutte</strong>, une <strong>dysurie</strong>, pouvant conduire à une <strong>vessie de lutte</strong> et une dégradation de la fonction rénale).</p></ul>"},{"i":"abdef0c2c804","n":51,"o":"51-3","u":"Étiologies","t":"Connaître la démarche diagnostique en cas de trouble mictionnel : orientation diagnostique","q":"Quelles sont les trois grandes catégories étiologiques des troubles mictionnels de l'enfant ?","a":"<p>Les trois grandes catégories étiologiques des troubles mictionnels de l'enfant sont :</p><ul><li>Les <strong>dysfonctions du bas appareil urinaire (TUBA)</strong>.</li><li>Les <strong>malformations congénitales</strong>.</li><li>Les <strong>causes neurologiques</strong>.</li></ul>"},{"i":"e74c5d0ad32d","n":51,"o":"51-3","u":"Étiologies","t":"Connaître la démarche diagnostique en cas de trouble mictionnel : orientation diagnostique","q":"Dans quel contexte doit-on évoquer une cause neurologique face à des troubles mictionnels chez l'enfant ?","a":"<p>Une cause neurologique (vessie neurologique) doit être SYSTEMATIQUEMENT évoquée et une <strong>anomalie médullaire congénitale occulte</strong> recherchée lorsque :</p><ul><li>La clinique et l'évolution ne correspondent pas à l'hypothèse fonctionnelle.</li><li>Les troubles persistent malgré une prise en charge adaptée.</li></ul>"},{"i":"ecce915c88b1","n":51,"o":"51-3","u":"Étiologies","t":"Connaître la démarche diagnostique en cas de trouble mictionnel : orientation diagnostique","q":"Qu'est-ce que la dyssynergie vésico-sphinctérienne et quelles en sont les conséquences chez l'enfant ?","a":"<p>La dyssynergie vésico-sphinctérienne est une anomalie de la phase de vidange caractérisée par une <strong>absence de relâchement sphinctérien au moment de la miction</strong>.</p><p>Ses conséquences peuvent être :</p><ul><li>L'apparition d'un <strong>résidu post-mictionnel</strong> (RPM) par défaut de relâchement périnéal.</li><li>L'évolution vers une <strong>grande vessie rétentionniste</strong> à mictions rares par hypocontractilité détrusorienne en cas de persistance.</li></ul>"},{"i":"ff322c6eaedb","n":51,"o":"51-3","u":"Étiologies","t":"Connaître la démarche diagnostique en cas de trouble mictionnel : orientation diagnostique","q":"Comment se manifeste une anomalie de la phase de remplissage du bas appareil urinaire chez l'enfant et quelles en sont les conséquences ?","a":"<p>Une anomalie de la phase de remplissage, telle qu'une contraction désinhibée primitive du détrusor (anciennement \"vessie hyperactive\"), se manifeste par :</p><ul><li>Des <strong>fuites urinaires diurnes et/ou nocturnes</strong>.</li><li>Une <strong>urgenturie</strong> et une <strong>pollakiurie</strong> (plus de 7 mictions/jour chez un enfant d'au moins 5 ans).</li><li>Des <strong>manœuvres de retenue</strong> (accroupissement, pincement de verge, croisement des jambes, agitation).</li></ul><p>Elle favorise les <strong>infections urinaires</strong> (IU) et/ou le <strong>reflux vésico-urétéral</strong> (RVU).</p>"},{"i":"409f7953e6fc","n":51,"o":"51-6","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une énurésie primaire","q":"Qu'est-ce qui caractérise spécifiquement l'énurésie primaire ?","a":"<p>L'énurésie primaire est caractérisée par le fait que l'enfant <strong>n'a jamais eu de nuit sèche</strong> sur une période de <strong>plus de 6 mois depuis la naissance</strong>.</p>"},{"i":"8ba5d3f9ccf1","n":51,"o":"51-6","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une énurésie primaire","q":"Comment réalise-t-on le diagnostic positif de l'énurésie primaire ?","a":"<p>Le diagnostic positif de l'énurésie primaire est <strong>exclusivement clinique</strong>. <strong>Aucun examen d'imagerie n'est indiqué en première intention</strong>.</p>"},{"i":"906126bcb188","n":51,"o":"51-6","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une énurésie primaire","q":"Quels sont les deux principaux mécanismes physiopathologiques sous-jacents aux sous-types de l'énurésie primaire isolée ?","a":"<ul><li>Le <strong>mécanisme polyurique par inversion du cycle de l'ADH</strong> (hormone antidiurétique), où le volume urinaire nocturne est supérieur au volume diurne, avec une osmolarité urinaire plus basse la nuit.</li><li>La <strong>faible capacité vésicale</strong>, définie par une capacité vésicale fonctionnelle inférieure à 70% de la capacité théorique, mesurée par un calendrier mictionnel de 48 heures.</li></ul>"},{"i":"ddf3d55e9f27","n":51,"o":"51-6","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une énurésie primaire","q":"Comment définit-on l'énurésie chez l'enfant ?","a":"<p>L'énurésie est une <strong>fuite involontaire d'urine pendant le sommeil</strong> chez un enfant âge de <strong>5 ans ou plus</strong>.</p>"}]};